  $$('[data-mobile-visibility]',sheet).forEach(b=>b.onclick=()=>transact(()=>{const bp=b.dataset.mobileVisibility,n=selectedAdded();if(n){if(bp==='desktop')n.advanced.visibility.desktop=!n.advanced.visibility.desktop;else{n.responsive.overrides[bp]??={};n.responsive.overrides[bp].visible=!nodeVisible(n,bp)}}else if(bp==='desktop')state.advanced.visibility.desktop=!state.advanced.visibility.desktop;else setResponsiveValue('visibility','visible',!effectiveVisibility(bp))},'Visibility updated'));
  $$('[data-mobile-reset]',sheet).forEach(b=>b.onclick=()=>transact(()=>{const n=selectedAdded();if(n)resetNodeResponsive(n,b.dataset.mobileReset)},'Reset to inherited'));
  $('[data-mobile-command="delete"]',sheet)?.addEventListener('click',()=>{deleteSelected();closeSheet()});
  $$('[data-mobile-bg]',sheet).forEach(b=>b.onclick=()=>transact(()=>state.background.mode=b.dataset.mobileBg,'Background mode updated'));
  $('#applyMobileContent',sheet)?.addEventListener('click',()=>transact(()=>{const n=selectedAdded();if(n){n.content.text=$('#mContentText',sheet).value;n.label=n.content.text;n.content.copy=$('#mContentCopy',sheet)?.value||'';n.content.cta=$('#mContentCta',sheet)?.value||'';n.content.alt=$('#mContentAlt',sheet)?.value||n.content.alt}else{state.content.headline=$('#mContentText',sheet).value;state.content.copy=$('#mContentCopy',sheet).value;state.content.cta=$('#mContentCta',sheet).value}},'Content applied'));
