const addCats={sections:['Hero','Features','Services','Pricing','Testimonials','FAQ','Team','Gallery','Booking','Contact','CTA','Footer'],elements:['Layout','Basic','Content','Interactive'],components:['Kohevo'],dynamic:['Kohevo','Content'],media:['Basic','Content'],templates:['Template'],ai:['AI'],kohevo:['Kohevo']};
function addCard(item,mobile=false){return `<article class="insert-card ${item.type==='business'?'business-card':''}" draggable="true" data-add-label="${esc(item.label)}"><div class="insert-thumb thumb-${item.cat.toLowerCase()}"><span>${item.icon}</span><button class="insert-fav" aria-label="Favorite ${esc(item.label)}">☆</button></div><div class="insert-card-copy"><b>${esc(item.label)}</b><small>${esc(item.desc)}</small></div><div class="insert-card-actions"><button class="insert-preview" data-preview="${esc(item.label)}">Preview</button><button class="insert-add" data-insert="${esc(item.label)}">Add</button></div>${item.type==='business'?'<em class="native-badge">KOHEVO</em>':''}${item.type==='template'?'<em class="native-badge template-badge">TEMPLATE</em>':''}</article>`}
function addItems(cat,query=''){const allowed=addCats[cat]||addCats.elements;const q=query.trim().toLowerCase();let items=addCatalog.filter(x=>allowed.includes(x.cat));if(q)items=items.filter(x=>`${x.label} ${x.desc} ${x.cat}`.toLowerCase().includes(q));return items}
function insertLibrary(item){transact(()=>{addNode(item.type,item.label,item.icon,{kind:item.type,identity:item.label,component:item.type==='business'?item.label:null})},`${item.label} inserted`);$('.insertion-line')?.classList.remove('drop-ready')}
function findItem(labelText){return addCatalog.find(x=>x.label===labelText)||{label:labelText,desc:'Inserted demo element',type:'element',icon:'＋'}}
function showInsertPreview(item){notify(`${item.label}: ${item.desc}`)}
function renderAddLibrary(tab='sections',query=''){const list=$('.category-list');if(!list)return;const items=addItems(tab,query);list.innerHTML=`<div class="library-meta"><span>${items.length} results</span><small>Find it → Preview it → Add it</small></div><div class="insert-grid">${items.length?items.map(x=>addCard(x)).join(''):`<div class="insert-empty"><b>No matches</b><span>Try a section, element or business term.</span></div>`}</div>`;$$('.insert-add',list).forEach(b=>b.onclick=()=>insertLibrary(findItem(b.dataset.insert)));$$('.insert-preview',list).forEach(b=>b.onclick=()=>showInsertPreview(findItem(b.dataset.preview)));$$('.insert-fav',list).forEach(b=>b.onclick=e=>{e.currentTarget.classList.toggle('saved');e.currentTarget.textContent=e.currentTarget.classList.contains('saved')?'★':'☆';notify(e.currentTarget.classList.contains('saved')?'Saved to favorites':'Removed from favorites')});$$('.insert-card',list).forEach(card=>{card.ondragstart=e=>{e.dataTransfer.setData('text/kohevo-insert',card.dataset.addLabel);e.dataTransfer.effectAllowed='copy';$('.insertion-line')?.classList.add('drop-ready')};card.ondragend=()=>$('.insertion-line')?.classList.remove('drop-ready')})}
function buildQuickInsert(){if($('.quick-insert-overlay'))return;const o=document.createElement('div');o.className='quick-insert-overlay';o.innerHTML=`<div class="quick-insert-dialog"><div class="quick-kicker">QUICK INSERT <kbd>ESC</kbd></div><input id="quickInsertSearch" placeholder="Search sections, elements or booking…" autofocus><div id="quickInsertResults"></div><small>↑ ↓ navigate · Enter insert</small></div>`;document.body.append(o);const input=$('#quickInsertSearch',o);const render=()=>{$('#quickInsertResults',o).innerHTML=addItems('elements',input.value).slice(0,8).map(x=>`<button class="quick-result" data-quick="${esc(x.label)}"><span>${x.icon}</span><b>${esc(x.label)}</b><small>${esc(x.cat)}</small></button>`).join('')||'<div class="quick-empty">No insert results</div>';$$('.quick-result',o).forEach(b=>b.onclick=()=>{insertLibrary(findItem(b.dataset.quick));o.classList.remove('visible')})};input.oninput=render;input.onkeydown=e=>{if(e.key==='Escape'){o.classList.remove('visible');return}if(e.key==='Enter'){const first=$('.quick-result',o);if(first)first.click()}};o.onclick=e=>{if(e.target===o)o.classList.remove('visible')};window.openQuickInsert=()=>{o.classList.add('visible');input.value='';render();setTimeout(()=>input.focus(),20)};render()}
function buildAddExperience(){buildQuickInsert();const tabs=$('.add-tabs');if(tabs){tabs.innerHTML=['Sections','Elements','Components','Dynamic','Media','Templates','AI'].map((x,i)=>`<button class="add-tab ${i===0?'active':''}" data-add-tab="${x.toLowerCase()}">${x}</button>`).join('');$$('.add-tab',tabs).forEach(b=>b.onclick=()=>{$$('.add-tab',tabs).forEach(x=>x.classList.toggle('active',x===b));renderAddLibrary(b.dataset.addTab,$('.search-box input')?.value||'')})}const search=$('.search-box input');if(search){search.placeholder='Search sections, elements, booking…';search.oninput=()=>renderAddLibrary($('.add-tab.active')?.dataset.addTab||'sections',search.value)}renderAddLibrary('sections');const stage=$('.canvas-stage');stage.ondragover=e=>{if(e.dataTransfer.types.includes('text/kohevo-insert')){e.preventDefault();$('.insertion-line')?.classList.add('drop-ready')}};stage.ondragleave=e=>{if(!stage.contains(e.relatedTarget))$('.insertion-line')?.classList.remove('drop-ready')};stage.ondrop=e=>{e.preventDefault();const labelText=e.dataTransfer.getData('text/kohevo-insert');if(labelText)insertLibrary(findItem(labelText))};}
function upgradeMobileAdd(){const drawer=$('.mobile-drawer[data-drawer="add"]');if(!drawer)return;drawer.innerHTML=`<div class="mobile-drawer-head"><b>Add to mobile page</b><button class="mobile-drawer-close">×</button></div><div class="mobile-add-chips">${['Sections','Elements','Kohevo','Templates'].map(x=>`<button data-mobile-cat="${x.toLowerCase()}">${x}</button>`).join('')}</div><input class="mobile-search" placeholder="Search mobile elements or booking…" /><div class="mobile-insert-list"></div>`;$('.mobile-drawer-close',drawer).onclick=closeDrawer;const render=()=>{$('.mobile-insert-list',drawer).innerHTML=addItems($('.mobile-add-chips button.active',drawer)?.dataset.mobileCat||'sections',$('.mobile-search',drawer).value).slice(0,12).map(x=>addCard(x,true)).join('')||'<div class="insert-empty">No mobile matches</div>';$$('.insert-add',drawer).forEach(b=>b.onclick=()=>insertLibrary(findItem(b.dataset.insert)));$$('.insert-preview',drawer).forEach(b=>b.onclick=()=>showInsertPreview(findItem(b.dataset.preview)))};$$('.mobile-add-chips button',drawer).forEach(b=>b.onclick=()=>{$$('.mobile-add-chips button',drawer).forEach(x=>x.classList.remove('active'));b.classList.add('active');render()});$('.mobile-add-chips button',drawer).classList.add('active');$('.mobile-search',drawer).oninput=render;render()}
const heroImage=$('.hero-image');setup();
